@androidx.media3.common.util.UnstableApi
public class PowerEfficiencyTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private Activity activity;private File file;private ListenableFuture<MediaController> connection;private MediaController music;private boolean oldActive,voice,silence;private Map<String,?> oldDownloads,oldHistory;
 @Before public void before(){oldActive=MediaDownloadService.activeDownload;voice=SpeechSettings.voice(c);silence=SpeechSettings.silence(c);oldDownloads=c.getSharedPreferences("downloads",0).getAll();oldHistory=c.getSharedPreferences(DownloadHistory.PREF,0).getAll();}
 private Object field(Object owner,String name)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private Object instance()throws Exception{Field f=VideoBackgroundService.class.getDeclaredField("instance");f.setAccessible(true);return f.get(null);}
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{boolean[] ready={false};for(int i=0;i<300;i++){ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(50);}fail("Power scenario did not become ready");}
 private void shell(String command)throws Exception{try(ParcelFileDescriptor p=ins.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
 private void restore(String name,Map<String,?> values){SharedPreferences.Editor e=c.getSharedPreferences(name,0).edit().clear();for(Map.Entry<String,?> entry:values.entrySet()){Object v=entry.getValue();String k=entry.getKey();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof Set)e.putStringSet(k,(Set<String>)v);}e.commit();}
 @After public void after()throws Exception{try{shell("input keyevent 224");shell("wm dismiss-keyguard");}catch(Exception ignored){}ins.runOnMainSync(()->{if(music!=null){music.stop();music.clearMediaItems();SpeechSettings.save(c,voice,silence);music.sendCustomCommand(new SessionCommand(SpeechSettings.COMMAND,Bundle.EMPTY),Bundle.EMPTY);}if(connection!=null)MediaController.releaseFuture(connection);c.stopService(new Intent(c,VideoBackgroundService.class));if(activity!=null)activity.finish();});ins.waitForIdleSync();MediaDownloadService.activeDownload=oldActive;restore("downloads",oldDownloads);restore(DownloadHistory.PREF,oldHistory);if(file!=null)file.delete();}
 private File fixture()throws Exception{file=File.createTempFile("onda-power-",".mp4",c.getCacheDir());try(InputStream in=ins.getContext().getAssets().open("power-background.mp4");OutputStream out=new FileOutputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return file;}
 private void report(String kind,JSONObject data)throws Exception{try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"power-"+kind+".json"))){out.write(data.toString(2).getBytes("UTF-8"));}}
 @Test public void downloadScreensObserveChangesWithoutRecurringIdleCallbacks()throws Exception{MediaDownloadService.activeDownload=true;c.getSharedPreferences("downloads",0).edit().putBoolean("busy",true).putString("status","Transferidos 1 MB").commit();activity=ins.startActivitySync(new Intent(c,DownloadsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->OndaApplication.userVisible(c));c.getSharedPreferences("downloads",0).edit().putString("status","Transferidos 2 MB").commit();waitFor(()->"Transferidos 2 MB".contentEquals(((TextView)field(activity,"status")).getText()));ins.waitForIdleSync();ins.runOnMainSync(()->{try{assertFalse(((Handler)field(activity,"handler")).hasCallbacks((Runnable)field(activity,"refresh")));}catch(Exception e){throw new RuntimeException(e);}});shell("input keyevent 223");waitFor(()->!OndaApplication.userVisible(c));c.getSharedPreferences("downloads",0).edit().putString("status","Transferidos 3 MB").commit();shell("input keyevent 224");shell("wm dismiss-keyguard");waitFor(()->OndaApplication.userVisible(c)&&"Transferidos 3 MB".contentEquals(((TextView)field(activity,"status")).getText()));ins.runOnMainSync(activity::finish);ins.waitForIdleSync();activity=ins.startActivitySync(new Intent(c,DownloadCenterActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));String id=DownloadHistory.add(c,"Power event fixture","https://example.org/video.mp4","mp4");waitFor(()->((List<DownloadHistory.Entry>)field(activity,"shown")).stream().anyMatch(e->e.id.equals(id)));ins.waitForIdleSync();ins.runOnMainSync(()->{try{assertFalse(((Handler)field(activity,"handler")).hasCallbacks((Runnable)field(activity,"tick")));}catch(Exception e){throw new RuntimeException(e);}});MediaDownloadService.activeDownload=false;c.getSharedPreferences("downloads",0).edit().putBoolean("busy",false).putLong("finished_at",SystemClock.elapsedRealtime()).commit();waitFor(()->!((Boolean)field(activity,"wasActive")));report("ui",new JSONObject().put("preferenceEventsUpdateUi",true).put("noRecurringDownloadScreenPoll",true).put("screenStateTracksVisibility",true).put("resumeRefreshesImmediately",true).put("completionEventUpdatesCenter",true));}
 @Test public void backgroundAudioAdvancesWithSparseSessionUpdatesAndReleasesWakeOnPause()throws Exception{File input=fixture();ins.runOnMainSync(()->VideoBackgroundService.start(c,new VideoBackgroundService.Snapshot(Uri.fromFile(input),"Power video","power.mp4",0,25000,1,0,false,new VideoLoop(),true)));waitFor(()->instance()!=null&&((org.videolan.libvlc.MediaPlayer)field(instance(),"player")).isPlaying()&&((org.videolan.libvlc.MediaPlayer)field(instance(),"player")).getTime()>800);android.media.session.MediaController[] control={null};PowerManager.WakeLock[] wake={null};long[] time={0};AtomicInteger changes=new AtomicInteger();android.media.session.MediaController.Callback callback=new android.media.session.MediaController.Callback(){@Override public void onPlaybackStateChanged(android.media.session.PlaybackState state){changes.incrementAndGet();}};ins.runOnMainSync(()->{try{control[0]=((android.media.session.MediaSession)field(instance(),"session")).getController();control[0].registerCallback(callback,new Handler(Looper.getMainLooper()));wake[0]=(PowerManager.WakeLock)field(instance(),"wake");assertTrue(wake[0].isHeld());}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(300);changes.set(0);ins.runOnMainSync(()->{try{time[0]=((org.videolan.libvlc.MediaPlayer)field(instance(),"player")).getTime();}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(4500);long[] advanced={0};ins.runOnMainSync(()->{try{long actual=((org.videolan.libvlc.MediaPlayer)field(instance(),"player")).getTime();advanced[0]=actual-time[0];assertTrue("Actual audio must advance",advanced[0]>3000);assertTrue("Session must not publish every 1.5 seconds: "+changes.get(),changes.get()<=1);android.media.session.PlaybackState state=control[0].getPlaybackState();long estimate=state.getPosition()+(long)((SystemClock.elapsedRealtime()-state.getLastPositionUpdateTime())*state.getPlaybackSpeed());assertTrue("Android extrapolation diverged from playback",Math.abs(estimate-actual)<1800);control[0].getTransportControls().seekTo(10000);}catch(Exception e){throw new RuntimeException(e);}});int sparse=changes.get();waitFor(()->((org.videolan.libvlc.MediaPlayer)field(instance(),"player")).getTime()>=9800);ins.runOnMainSync(()->control[0].getTransportControls().pause());waitFor(()->!wake[0].isHeld()&&!((org.videolan.libvlc.MediaPlayer)field(instance(),"player")).isPlaying());ins.runOnMainSync(()->{control[0].unregisterCallback(callback);c.stopService(new Intent(c,VideoBackgroundService.class));});waitFor(()->instance()==null);assertFalse(wake[0].isHeld());report("background",new JSONObject().put("actualAudioAdvanceMs",advanced[0]).put("stateCallbacksDuring4500ms",sparse).put("androidExtrapolationChecked",true).put("seekAndPauseRemainImmediate",true).put("wakeReleased",true));}
 @Test public void lyricsFollowVerseBoundariesAndMusicNeverSelectsVideoTracks()throws Exception{File input=fixture();ListenableFuture<MediaController>[] future=new ListenableFuture[1];ins.runOnMainSync(()->future[0]=new MediaController.Builder(c,new SessionToken(c,new ComponentName(c,PlaybackService.class))).buildAsync());connection=future[0];music=connection.get(15,TimeUnit.SECONDS);ins.runOnMainSync(()->{music.pause();music.setRepeatMode(Player.REPEAT_MODE_OFF);music.setShuffleModeEnabled(false);SpeechSettings.save(c,false,false);music.sendCustomCommand(new SessionCommand(SpeechSettings.COMMAND,Bundle.EMPTY),Bundle.EMPTY);music.setMediaItem(new MediaItem.Builder().setMediaId("power-lyrics").setUri(Uri.fromFile(input)).setMediaMetadata(new MediaMetadata.Builder().setTitle("").setArtist("").build()).build());music.prepare();});waitFor(()->music.getPlaybackState()==Player.STATE_READY&&music.getDuration()>0);activity=ins.startActivitySync(new Intent(c,LyricsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->field(activity,"player")!=null);LyricsRepository.Result synchronizedLyrics=new LyricsRepository.Result(new JSONObject().put("syncedLyrics","[00:00.00]A\n[00:05.00]B\n[00:10.00]C"));ins.runOnMainSync(()->{try{Method clear=LyricsActivity.class.getDeclaredMethod("clear"),show=LyricsActivity.class.getDeclaredMethod("show",LyricsRepository.Result.class);clear.setAccessible(true);show.setAccessible(true);clear.invoke(activity);show.invoke(activity,synchronizedLyrics);music.play();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->music.isPlaying()&&music.getCurrentPosition()>300&&((Integer)field(activity,"highlighted"))==0);long[] ticks={0};ins.runOnMainSync(()->{try{ticks[0]=(Long)field(activity,"lyricUpdates");boolean audio=false;for(Tracks.Group group:music.getCurrentTracks().getGroups()){if(group.getType()==C.TRACK_TYPE_VIDEO)assertFalse(group.isSelected());if(group.getType()==C.TRACK_TYPE_AUDIO&&group.isSelected())audio=true;}assertTrue(audio);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(2200);ins.runOnMainSync(()->{try{assertTrue("Lyrics should await the next verse",(Long)field(activity,"lyricUpdates")-ticks[0]<=1);music.seekTo(6000);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->((Integer)field(activity,"highlighted"))==1);LyricsRepository.Result plain=new LyricsRepository.Result(new JSONObject().put("plainLyrics","Texto sem sincronização"));ins.runOnMainSync(()->{try{Method clear=LyricsActivity.class.getDeclaredMethod("clear"),show=LyricsActivity.class.getDeclaredMethod("show",LyricsRepository.Result.class);clear.setAccessible(true);show.setAccessible(true);clear.invoke(activity);show.invoke(activity,plain);}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();ins.runOnMainSync(()->{try{ticks[0]=(Long)field(activity,"lyricUpdates");}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(1100);ins.runOnMainSync(()->{try{assertEquals(ticks[0],((Long)field(activity,"lyricUpdates")).longValue());ticks[0]=music.getCurrentPosition();}catch(Exception e){throw new RuntimeException(e);}});shell("input keyevent 223");Thread.sleep(1500);ins.runOnMainSync(()->assertTrue("Screen off must not stop music",music.getCurrentPosition()>ticks[0]+500));shell("input keyevent 224");shell("wm dismiss-keyguard");report("lyrics",new JSONObject().put("nextVerseScheduling",true).put("seekUpdatesVerseImmediately",true).put("plainLyricsHaveNoPeriodicPoll",true).put("musicVideoTrackDisabled",true).put("audioContinuesWithScreenOff",true));}
}
